<template><div class="app-container"><el-alert title="设备绑定码仅保存摘要，新增或重置时输入一次，后台不会回显明文。" type="info" :closable="false" style="margin-bottom:16px"/><div class="filter-container"><el-input v-model="query.keyword" placeholder="设备编号/型号" clearable style="width:240px"/><el-select v-model="query.status" clearable placeholder="状态" style="width:130px"><el-option label="启用" value="ENABLED"/><el-option label="停用" value="DISABLED"/></el-select><el-button type="primary" @click="load">查询</el-button><el-button @click="edit()">新增设备</el-button></div><el-table v-loading="loading" :data="list" border><el-table-column prop="deviceSn" label="设备编号" min-width="180"/><el-table-column prop="providerCode" label="厂商"/><el-table-column prop="deviceType" label="类型"/><el-table-column prop="deviceModel" label="型号"/><el-table-column prop="boundUserName" label="绑定用户"/><el-table-column prop="lastSyncTime" label="最后同步" min-width="160"/><el-table-column prop="status" label="状态" width="90"/><el-table-column label="操作" width="80"><template slot-scope="{row}"><el-button type="text" @click="edit(row)">编辑</el-button></template></el-table-column></el-table><el-dialog :visible.sync="visible" :title="form.id?'编辑设备':'新增设备'" width="520px"><el-form label-width="100px"><el-form-item label="设备编号"><el-input v-model="form.deviceSn"/></el-form-item><el-form-item label="厂商编码"><el-input v-model="form.providerCode"/></el-form-item><el-form-item label="设备类型"><el-input v-model="form.deviceType" placeholder="如 GLUCOSE_METER"/></el-form-item><el-form-item label="设备型号"><el-input v-model="form.deviceModel"/></el-form-item><el-form-item label="绑定码"><el-input v-model="form.bindCode" show-password :placeholder="form.id?'留空表示不重置':'新增设备必填'"/></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option label="启用" value="ENABLED"/><el-option label="停用" value="DISABLED"/></el-select></el-form-item></el-form><span slot="footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></span></el-dialog></div></template><script>import{getJkHealthDeviceList,saveJkHealthDevice}from'@/api/jkBusiness';export default{data(){return{query:{page:1,limit:20},list:[],loading:false,visible:false,form:{status:'ENABLED'}}},created(){this.load()},methods:{rows(r){return(r&&r.list)||(r&&r.data&&r.data.list)||r.data||r||[]},load(){this.loading=true;getJkHealthDeviceList(this.query).then(r=>this.list=this.rows(r)).finally(()=>this.loading=false)},edit(row){this.form=row?Object.assign({},row,{bindCode:''}):{status:'ENABLED'};this.visible=true},save(){saveJkHealthDevice(this.form).then(()=>{this.$message.success('保存成功');this.visible=false;this.load()})}}}</script>